import csv
import re
from decimal import Decimal

_AMOUNT_PATTERN = re.compile(r"-?[0-9]+(?:\.[0-9]{1,2})?")
_REQUIRED_HEADERS = {"id", "team", "amount", "status"}
_VALID_STATUSES = {"settled", "pending", "cancelled"}


def read_rows(lines):
    reader = csv.reader(lines, strict=True)
    rows = []
    seen_ids = set()

    try:
        header = next(reader, None)
        if (
            header is None
            or len(header) != 4
            or set(header) != _REQUIRED_HEADERS
        ):
            raise ValueError("Header must contain exactly id, team, amount, status")

        for fields in reader:
            if len(fields) != 4:
                raise ValueError("Every data row must contain exactly four fields")

            row = dict(zip(header, (value.strip() for value in fields)))

            if not row["id"] or not row["team"]:
                raise ValueError("id and team must be nonempty")
            if row["id"] in seen_ids:
                raise ValueError("Duplicate id: {!r}".format(row["id"]))
            if row["status"] not in _VALID_STATUSES:
                raise ValueError("Invalid status: {!r}".format(row["status"]))
            if _AMOUNT_PATTERN.fullmatch(row["amount"]) is None:
                raise ValueError("Invalid amount: {!r}".format(row["amount"]))

            row["amount"] = Decimal(row["amount"])
            seen_ids.add(row["id"])
            rows.append(row)

    except csv.Error as exc:
        raise ValueError("Malformed CSV: {}".format(exc)) from exc

    return rows

def _format_cents(cents):
    sign = "-" if cents < 0 else ""
    whole, remainder = divmod(abs(cents), 100)

    chunks = []
    while whole:
        whole, chunk = divmod(whole, 1_000_000_000)
        chunks.append(chunk)

    if chunks:
        integer_part = str(chunks.pop())
        integer_part += "".join(f"{chunk:09d}" for chunk in reversed(chunks))
    else:
        integer_part = "0"

    return f"{sign}{integer_part}.{remainder:02d}"


def summarize(rows):
    totals = {}
    for row in rows:
        if row.get("status") != "settled":
            continue

        sign, digits, exponent = row["amount"].as_tuple()
        cents = 0
        for digit in digits:
            cents = cents * 10 + digit
        cents *= 10 ** (exponent + 2)
        if sign:
            cents = -cents

        team = row["team"]
        totals[team] = totals.get(team, 0) + cents

    return {team: _format_cents(cents) for team, cents in totals.items()}

