from decimal import Decimal, MAX_EMAX, MIN_EMIN, localcontext


def summarize(rows):
    totals = {}
    with localcontext() as context:
        context.Emax = MAX_EMAX
        context.Emin = MIN_EMIN
        for row in rows:
            if row['status'] != 'settled':
                continue
            team = row['team']
            total = totals.get(team, Decimal(0))
            amount = row['amount']
            # Allow all integer digits, two fractional digits, and a carry.
            context.prec = max(total.adjusted(), amount.adjusted(), 0) + 4
            totals[team] = total + amount
    return {team: format(total if total else Decimal(0), '.2f')
            for team, total in totals.items()}
